final readonly class ModelBoundProfileDispositionService
{
 private string $openings;private string $reconciliations;private string $findings;private string $occupancy;private string $dispositions;
 public function __construct(string$root,private ProfileExaminationDispositionCognitionGateway$cognition){$s=$root.'/var/imperium/offices/senate';$this->openings=$s.'/model-bound-profile-disposition-authority-openings';$this->reconciliations=$s.'/model-bound-profile-reconciliations';$this->findings=$s.'/model-bound-profile-senator-findings';$this->occupancy=$s.'/occupancy';$this->dispositions=$s.'/model-bound-profile-dispositions';}
 public function decide(string$openingId,string$authorityId,string$bindingId):array
 {
  foreach(glob($this->dispositions.'/*.json')?:[]as$p){$x=$this->read($p,'S304_MODEL_BOUND_DISPOSITION_CONFLICT');if(($x['source_disposition_authority_opening']['id']??null)===$openingId)return$x;}
  $o=$this->read($this->openings.'/'.$openingId.'.json','S299_MODEL_BOUND_DISPOSITION_OPENING_ABSENT');$r=$this->read($this->reconciliations.'/'.($o['source_reconciliation']['id']??'').'.json','S300_MODEL_BOUND_RECONCILIATION_ABSENT');$l=$this->read($this->occupancy.'/'.$bindingId.'.json','S301_LORD_SPEAKER_UNAVAILABLE');$a=$o['disposition_authority']??[];
  if(!$this->ok($o)||!$this->ok($r)||!$this->ok($l)||($o['source_reconciliation']['digest']??null)!==$r['record_digest']||'PROFILE_EXAMINATION_DISPOSITION_AUTHORITY_OPENED_PENDING_LORD_SPEAKER_DISPOSITION'!==($o['status']??null)||true!==($o['senate_disposition_authority']??null)||null!==($o['disposition']??null)||$authorityId!==($a['authority_id']??null)||true!==($a['authority_single_use']??null)||true!==($a['security_block_must_be_preserved']??null)||['APPROVED','RETURN_FOR_REVISION','REFUSED','UNRESOLVED']!==($a['permitted_dispositions']??null)||($o['lord_speaker']['binding_id']??null)!==$bindingId||($o['lord_speaker']['binding_digest']??null)!==$l['record_digest']||'senate.lord-speaker'!==($l['seat']??null)||'ACTIVE'!==($l['status']??null)||true!==($l['binding_atomic']??null)||true===($l['execution_authority']??null)||($o['mandatory_security_blocking_condition']??null)!==($r['mandatory_security_blocking_condition']??null)||($o['subject_profile']??null)!==($r['subject_profile']??null))throw new \RuntimeException('S302_MODEL_BOUND_DISPOSITION_CHAIN_INVALID');
