  $authority=['disposition_authority_id'=>$authorityId,'available_finding_references'=>$refs,'permitted_dispositions'=>$a['permitted_dispositions'],'mandatory_security_blocking_condition'=>$o['mandatory_security_blocking_condition'],'profile_approval_authority'=>false];$d=$this->cognition->decide($authority,$found,$r['reconciliation']);$this->validate($d,$refs);if(true===$o['mandatory_security_blocking_condition']&&'APPROVED'===$d['disposition'])throw new \RuntimeException('S306_MODEL_BOUND_PROFILE_SECURITY_VETO');
  $id='model-bound-profile-disposition-'.substr(hash('sha256',CanonicalJson::encode([$openingId,$o['record_digest'],$authorityId,$d])),0,20);return$this->save($id,['schema'=>'imperium.senate-model-bound-profile-disposition/v1','disposition_id'=>$id,'instance_id'=>$o['instance_id'],'case_id'=>$o['case_id'],'case_digest'=>$o['case_digest'],'source_disposition_authority_opening'=>['id'=>$openingId,'digest'=>$o['record_digest']],'source_reconciliation'=>$o['source_reconciliation'],'subject_profile'=>$o['subject_profile'],'admitted_findings'=>$r['admitted_findings'],'reconciliation'=>$r['reconciliation'],'mandatory_security_blocking_condition'=>$o['mandatory_security_blocking_condition'],'lord_speaker'=>$o['lord_speaker'],'disposition_authority'=>['id'=>$authorityId,'consumed'=>true,'continuing_authority'=>false],'decision'=>$d,'status'=>'PROFILE_EXAMINATION_DISPOSITION_SEALED_PENDING_IMPERATOR_PROFILE_APPROVAL','senate_disposition_authority_consumed'=>true,'imperator_profile_approval_pending'=>true,'profile_approval_authority'=>false,'profile_installation_authority'=>false,'profile_activation_authority'=>false,'seat_binding_authority'=>false,'deployment_authority'=>false,'execution_authority'=>false,'sealed'=>true]);
 }
 private function validate(array$d,array$refs):void{$k=array_keys($d);sort($k);if(['disposition','finding_references','limitations','rationale','reconciliation_treatment','uncertainties']!==$k||!in_array($d['disposition']??null,['APPROVED','RETURN_FOR_REVISION','REFUSED','UNRESOLVED'],true)||$refs!==($d['finding_references']??null)||!is_string($d['rationale']??null)||''===trim($d['rationale'])||!is_string($d['reconciliation_treatment']??null)||''===trim($d['reconciliation_treatment']))throw new \RuntimeException('S305_MODEL_BOUND_DISPOSITION_INVALID');foreach(['limitations','uncertainties']as$x)if(!is_array($d[$x]??null)||!array_is_list($d[$x]))throw new \RuntimeException('S305_MODEL_BOUND_DISPOSITION_INVALID');}
 private function read($p,$e):array{if(!is_file($p))throw new \RuntimeException($e);return json_decode((string)file_get_contents($p),true,512,JSON_THROW_ON_ERROR);}private function ok(array$r):bool{$d=$r['record_digest']??null;unset($r['record_digest']);return is_string($d)&&hash_equals($d,hash('sha256',CanonicalJson::encode($r)));}private function save($id,array$r):array{if(!is_dir($this->dispositions))mkdir($this->dispositions,0770,true);$r['record_digest']=hash('sha256',CanonicalJson::encode($r));$p=$this->dispositions.'/'.$id.'.json';if(is_file($p)){if($this->read($p,'S304_MODEL_BOUND_DISPOSITION_CONFLICT')!==$r)throw new \RuntimeException('S304_MODEL_BOUND_DISPOSITION_CONFLICT');return$r;}file_put_contents($p,json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n",LOCK_EX);return$r;}
}
